using System;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;
namespace XuanwuTools { public static class RockPlacementTool {
 [MenuItem(Common.Menu+"04 Place prefabs from JSON")] public static void Place()=>Common.Run(()=>{var c=Common.Read<Layout>();Common.SceneGuard(c.scenePath);if(c.placements==null||c.placements.Length==0||c.placements.Length>500||string.IsNullOrEmpty(c.rootName)||!c.rootName.StartsWith("XuanwuGenerated_"))throw new Exception("Invalid placements/root");if(c.placements.Any(p=>string.IsNullOrWhiteSpace(p.id)||p.id.Contains("/")||!Common.Finite(p.position)||!Common.Finite(p.euler)||!Common.Finite(p.scale)||p.scale.x<=0||p.scale.y<=0||p.scale.z<=0)||c.placements.Select(p=>p.id).Distinct().Count()!=c.placements.Length)throw new Exception("Invalid/duplicate IDs or transforms");var roots=SceneManager.GetActiveScene().GetRootGameObjects().Where(x=>x.name==c.rootName).ToArray();if(roots.Length>1)throw new Exception("Ambiguous root");var root=roots.FirstOrDefault();var todo=new List<Placement>();foreach(var p in c.placements){if(root&&root.transform.Find(p.id))continue;if(string.IsNullOrEmpty(p.prefab)||!p.prefab.StartsWith("Assets/")||!p.prefab.EndsWith(".prefab")||!AssetDatabase.LoadAssetAtPath<GameObject>(p.prefab))throw new Exception("Invalid prefab "+p.prefab);todo.Add(p);}if(!Common.Confirm("Placement dry-run",$"Create {todo.Count}; skip {c.placements.Length-todo.Count} existing IDs. Review explicit placements and safe corridor before applying."))return;int g=Undo.GetCurrentGroup();try{if(!root){root=new GameObject(c.rootName);Undo.RegisterCreatedObjectUndo(root,"Create root");}foreach(var p in todo){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(p.prefab),root.transform);Undo.RegisterCreatedObjectUndo(o,"Place rock");o.name=p.id;o.transform.SetPositionAndRotation(p.position,Quaternion.Euler(p.euler));o.transform.localScale=p.scale;}EditorSceneManager.MarkSceneDirty(root.scene);Undo.CollapseUndoOperations(g);}catch{Undo.RevertAllDownToGroup(g);throw;}Common.Report("placement",$"created={todo.Count}; existing IDs skipped, not moved. Check route and rock backs.");});}}
